 const pool=key==='intel'?intelSites.filter(t=>!t.complete):key==='sam'?lights.filter(t=>t.health>0).map(t=>({...t,type:'sam'})):key==='ufo'?aliens:['fighter','blackhawk','sr71'].includes(key)?aircraft.filter(t=>t.type===key):targets.filter(t=>!t.enemy&&!t.lift&&(t.type===key||key==='cow'&&t.type==='gold'));
