 if(targets.includes(target)&&!target.enemy){targets=targets.filter(t=>t!==target);burst(target.x,target.y,25,'#ffb058',140,target.z);dispatch('GROUND CONTACT DESTROYED • NO CAPTURE CREDIT',2);}
